**`web/src/hooks/useMemoSorting.ts`** — useMemoSorting(function), getMemoSortTime(function), UseMemoSortingOptions(interface), UseMemoSortingResult(interface)

```typescript
1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import dayjs from "dayjs";
3	import { useMemo } from "react";
4	import { type MemoTimeBasis, useView } from "@/contexts/ViewContext";
5	import { State } from "@/types/proto/api/v1/common_pb";
6	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
7	
8	export interface UseMemoSortingOptions {
9	  pinnedFirst?: boolean;
10	  state?: State;
11	}
12	
13	export interface UseMemoSortingResult {
14	  listSort: (memos: Memo[]) => Memo[];
15	  orderBy: string;
16	}
17	
18	const getMemoSortTime = (memo: Memo, timeBasis: MemoTimeBasis): Date | undefined => {
19	  const timestamp = timeBasis === "update_time" ? memo.updateTime : memo.createTime;
20	  return timestamp ? timestampDate(timestamp) : undefined;
21	};
22	
23	// Moves the memo with the given name to the front of the list, above pinned
24	// memos, so a freshly created memo is immediately visible. Returns the input
25	// unchanged when the name is null, absent, or already first.
26	export const hoistMemoToFront = (memos: Memo[], name: string | null): Memo[] => {
27	  if (!name) return memos;
28	  const index = memos.findIndex((memo) => memo.name === name);
29	  if (index <= 0) return memos;
30	  const reordered = memos.slice();
31	  const [memo] = reordered.splice(index, 1);
32	  reordered.unshift(memo);
33	  return reordered;
34	};
35	
36	export const useMemoSorting = (options: UseMemoSortingOptions = {}): UseMemoSortingResult => {
37	  const { pinnedFirst = false, state = State.NORMAL } = options;
38	  const { orderByTimeAsc, timeBasis } = useView();
39	
40	  // Generate orderBy string for API
41	  const orderBy = useMemo(() => {
42	    const timeOrder = orderByTimeAsc ? `${timeBasis} asc` : `${timeBasis} desc`;
43	    return pinnedFirst ? `pinned desc, ${timeOrder}` : timeOrder;
44	  }, [pinnedFirst, orderByTimeAsc, timeBasis]);
45	
46	  // Generate listSort function for client-side sorting
47	  const listSort = useMemo(() => {
48	    return (memos: Memo[]): Memo[] => {
49	      return memos
50	        .filter((memo) => memo.state === state)
51	        .sort((a, b) => {
52	          // First, sort by pinned status if enabled
53	          if (pinnedFirst && a.pinned !== b.pinned) {
54	            return b.pinned ? 1 : -1;
55	          }
56	
57	          // Then sort by the selected time field.
58	          const aTime = getMemoSortTime(a, timeBasis);
59	          const bTime = getMemoSortTime(b, timeBasis);
60	          return orderByTimeAsc ? dayjs(aTime).unix() - dayjs(bTime).unix() : dayjs(bTime).unix() - dayjs(aTime).unix();
61	        });
62	    };
63	  }, [pinnedFirst, state, orderByTimeAsc, timeBasis]);
64	
65	  return { listSort, orderBy };
66	};
```

**`web/src/components/MemoEditor/hooks/useLinkMemo.ts`** — useLinkMemo(function), UseLinkMemoParams(interface)

```typescript
1	import { create } from "@bufbuild/protobuf";
2	import { useEffect, useMemo, useState } from "react";
3	import { memoServiceClient } from "@/connect";
4	import { useDebouncedEffect } from "@/hooks";
5	import useCurrentUser from "@/hooks/useCurrentUser";
6	import { DEFAULT_LIST_MEMOS_PAGE_SIZE } from "@/lib/constants";
7	import { buildMemoCreatorFilter } from "@/lib/resource-names";
8	import {
9	  type Memo,
10	  type MemoRelation,
11	  MemoRelation_MemoSchema,
12	  MemoRelation_Type,
13	  MemoRelationSchema,
14	} from "@/types/proto/api/v1/memo_service_pb";
15	
16	interface UseLinkMemoParams {
17	  isOpen: boolean;
18	  currentMemoName?: string;
19	  existingRelations: MemoRelation[];
20	  onAddRelation: (relation: MemoRelation) => void;
21	}
22	
23	export const useLinkMemo = ({ isOpen, currentMemoName, existingRelations, onAddRelation }: UseLinkMemoParams) => {
24	  const user = useCurrentUser();
25	  const [searchText, setSearchText] = useState("");
26	  const [isFetching, setIsFetching] = useState(true);
27	  const [fetchedMemos, setFetchedMemos] = useState<Memo[]>([]);
28	
29	  const filteredMemos = fetchedMemos.filter((memo) => memo.name !== currentMemoName);
30	
31	  const linkedMemoNames = useMemo(() => new Set(existingRelations.map((r) => r.relatedMemo?.name)), [existingRelations]);
32	
33	  const isAlreadyLinked = (memoName: string): boolean => linkedMemoNames.has(memoName);
34	
35	  useEffect(() => {
36	    if (isOpen) {
37	      setSearchText("");
38	    }
39	  }, [isOpen]);
40	
41	  useDebouncedEffect(
42	    async () => {
43	      if (!isOpen) return;
44	
45	      setIsFetching(true);
46	      try {
47	        const conditions: string[] = [];
48	        const creatorFilter = buildMemoCreatorFilter(user?.name ?? "");
49	        if (creatorFilter) {
50	          conditions.push(creatorFilter);
51	        }
52	        if (searchText) {
53	          conditions.push(`content.contains("${searchText}")`);
54	        }
55	        const { memos } = await memoServiceClient.listMemos({
56	          pageSize: DEFAULT_LIST_MEMOS_PAGE_SIZE,
57	          filter: conditions.join(" && "),
58	        });
59	        setFetchedMemos(memos);
60	      } catch (error) {
61	        console.error(error);
62	      } finally {
63	        setIsFetching(false);
64	      }
65	    },
66	    300,
67	    [isOpen, searchText],
68	  );
69	
70	  const addMemoRelation = (memo: Memo) => {
71	    const relation = create(MemoRelationSchema, {
72	      type: MemoRelation_Type.REFERENCE,
73	      relatedMemo: create(MemoRelation_MemoSchema, {
74	        name: memo.name,
75	        snippet: memo.snippet,
76	      }),
77	    });
78	    onAddRelation(relation);
79	  };
80	
81	  return {
82	    searchText,
83	    setSearchText,
84	    isFetching,
85	    filteredMemos,
86	    addMemoRelation,
87	    isAlreadyLinked,
88	  };
89	};
```

**`web/src/components/MemoEditor/hooks/useMemoSave.ts`** — useMemoSave(function), UseMemoSaveOptions(interface)

```typescript
1	import { useQueryClient } from "@tanstack/react-query";
2	import { useCallback } from "react";
3	import { toast } from "react-hot-toast";
4	import { useNewMemo } from "@/contexts/NewMemoContext";
5	import { memoKeys } from "@/hooks/useMemoQueries";
6	import { userKeys } from "@/hooks/useUserQueries";
7	import { handleError } from "@/lib/error";
8	import type { Visibility } from "@/types/proto/api/v1/memo_service_pb";
9	import { useTranslate } from "@/utils/i18n";
10	import { errorService, memoService, validationService } from "../services";
11	import { useEditorContext } from "../state";
12	
13	interface UseMemoSaveOptions {
14	  memoName?: string;
15	  parentMemoName?: string;
16	  defaultVisibility?: Visibility;
17	  defaultCreateTime?: Date;
18	  discardDraft: () => void;
19	  onConfirm?: (memoName: string) => void;
20	  onCancel?: () => void;
21	}
22	
23	/**
24	 * Owns the editor's save transaction and its post-save cache/state updates.
25	 * Keeping this workflow outside the shell makes saving identical whether it is
26	 * triggered by the toolbar or the editor keyboard shortcut.
27	 */
28	export function useMemoSave({
29	  memoName,
30	  parentMemoName,
31	  defaultVisibility,
32	  defaultCreateTime,
33	  discardDraft,
34	  onConfirm,
35	  onCancel,
36	}: UseMemoSaveOptions): () => Promise<void> {
37	  const t = useTranslate();
38	  const queryClient = useQueryClient();
39	  const { markNewMemo } = useNewMemo();
40	  const { actions, dispatch, getState } = useEditorContext();
41	
42	  return useCallback(async () => {
43	    const state = getState();
44	    const { valid, reason } = validationService.canSave(state);
45	    if (!valid) {
46	      toast.error(reason || "Cannot save");
47	      return;
48	    }
49	
50	    dispatch(actions.setLoading("saving", true));
51	
52	    try {
53	      const result = await memoService.save(state, { memoName, parentMemoName });
54	
55	      if (!result.hasChanges) {
56	        toast.error(t("editor.no-changes-detected"));
57	        onCancel?.();
58	        return;
59	      }
60	
61	      // Prevent the autosave unmount flush from restoring the saved draft.
62	      discardDraft();
63	
64	      const invalidationPromises = [
65	        queryClient.invalidateQueries({ queryKey: memoKeys.lists() }),
66	        queryClient.invalidateQueries({ queryKey: userKeys.stats() }),
67	      ];
68	      if (memoName) {
69	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.detail(memoName) }));
70	      }
71	      if (parentMemoName) {
72	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.comments(parentMemoName) }));
73	      }
74	      await Promise.all(invalidationPromises);
75	
76	      dispatch(actions.reset());
77	      if (!memoName && defaultVisibility) {
78	        dispatch(actions.setMetadata({ visibility: defaultVisibility }));
79	      }
80	      // Reset creates a fresh editor state, so restore calendar-derived values
81	      // for the next memo created without remounting this composer.
82	      if (!memoName && defaultCreateTime) {
83	        dispatch(actions.setTimestamps({ createTime: defaultCreateTime, updateTime: defaultCreateTime }));
84	      }
85	
86	      if (!memoName && !parentMemoName) {
87	        markNewMemo(result.memoName);
88	      }
89	      onConfirm?.(result.memoName);
90	    } catch (error) {
91	      handleError(error, toast.error, {
92	        context: "Failed to save memo",
93	        fallbackMessage: errorService.getErrorMessage(error),
94	      });
95	    } finally {
96	      dispatch(actions.setLoading("saving", false));
97	    }
98	  }, [
99	    actions,
100	    defaultCreateTime,
101	    defaultVisibility,
102	    discardDraft,
103	    dispatch,
104	    getState,
105	    markNewMemo,
106	    memoName,
107	    onCancel,
108	    onConfirm,
109	    parentMemoName,
110	    queryClient,
111	    t,
112	  ]);
113	}
```

**`web/src/hooks/useMemoShareQueries.ts`** — useMemoShares(function), memoShareKeys(constant), useCreateMemoShare(function), list(function), byShare(function), useDeleteMemoShare(function), useSharedMemo(function)

```typescript
1	import { create } from "@bufbuild/protobuf";
2	import { timestampFromDate } from "@bufbuild/protobuf/wkt";
3	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
4	import { memoServiceClient } from "@/connect";
5	import type { Attachment } from "@/types/proto/api/v1/attachment_service_pb";
6	import type { MemoShare } from "@/types/proto/api/v1/memo_service_pb";
7	import {
8	  CreateMemoShareRequestSchema,
9	  DeleteMemoShareRequestSchema,
10	  GetMemoByShareRequestSchema,
11	  ListMemoSharesRequestSchema,
12	  MemoShareSchema,
13	} from "@/types/proto/api/v1/memo_service_pb";
14	
15	// Query keys factory for share-related cache management.
16	export const memoShareKeys = {
17	  all: ["memo-shares"] as const,
18	  list: (memoName: string) => [...memoShareKeys.all, "list", memoName] as const,
19	  byShare: (shareId: string) => [...memoShareKeys.all, "by-share", shareId] as const,
20	};
21	
22	/** Lists all active share links for a memo (creator-only). */
23	export function useMemoShares(memoName: string, options?: { enabled?: boolean }) {
24	  return useQuery({
25	    queryKey: memoShareKeys.list(memoName),
26	    queryFn: async () => {
27	      const response = await memoServiceClient.listMemoShares(create(ListMemoSharesRequestSchema, { parent: memoName }));
28	      return response.memoShares;
29	    },
30	    enabled: options?.enabled ?? !!memoName,
31	  });
32	}
33	
34	/** Creates a new share link for a memo. */
35	export function useCreateMemoShare() {
36	  const queryClient = useQueryClient();
37	  return useMutation({
38	    mutationFn: async ({ memoName, expireTime }: { memoName: string; expireTime?: Date }) => {
39	      const memoShare = create(MemoShareSchema, {
40	        expireTime: expireTime ? timestampFromDate(expireTime) : undefined,
41	      });
42	      const response = await memoServiceClient.createMemoShare(create(CreateMemoShareRequestSchema, { parent: memoName, memoShare }));
43	      return response;
44	    },
45	    onSuccess: (_data, variables) => {
46	      queryClient.invalidateQueries({ queryKey: memoShareKeys.list(variables.memoName) });
47	    },
48	  });
49	}
50	
51	/** Revokes (deletes) a share link. */
52	export function useDeleteMemoShare() {
53	  const queryClient = useQueryClient();
54	  return useMutation({
55	    mutationFn: async ({ name, memoName }: { name: string; memoName: string }) => {
56	      await memoServiceClient.deleteMemoShare(create(DeleteMemoShareRequestSchema, { name }));
57	      return memoName;
58	    },
59	    onSuccess: (_data, variables) => {
60	      queryClient.invalidateQueries({ queryKey: memoShareKeys.list(variables.memoName) });
61	    },
62	  });
63	}
64	
65	/** Resolves a share token to its memo. Used by the public SharedMemo page. */
66	export function useSharedMemo(shareId: string, options?: { enabled?: boolean }) {
67	  return useQuery({
68	    queryKey: memoShareKeys.byShare(shareId),
69	    queryFn: async () => {
70	      const memo = await memoServiceClient.getMemoByShare(create(GetMemoByShareRequestSchema, { shareId }));
71	      return memo;
72	    },
73	    enabled: options?.enabled ?? !!shareId,
74	    retry: false, // Don't retry NOT_FOUND — the link is invalid or expired
75	  });
76	}
77	
78	/**
79	 * Returns the share URL for a MemoShare resource.
80	 * The token is the last path segment of the share name (memos/{uid}/shares/{token}).
81	 */
82	export function getShareUrl(share: MemoShare): string {
83	  const token = share.name.split("/").pop() ?? "";
84	  return `${window.location.origin}/memos/shares/${token}`;
85	}
86	
87	/**
88	 * Returns the token portion of a MemoShare resource name.
89	 * Format: memos/{memo}/shares/{token}
90	 */
91	export function getShareToken(share: MemoShare): string {
92	  return share.name.split("/").pop() ?? "";
93	}
94	
95	/** Rewrites attachment URLs to include a share token for unauthenticated access. */
96	export function withShareAttachmentLinks(attachments: Attachment[], token: string): Attachment[] {
97	  return attachments.map((a) => {
98	    if (a.externalLink) return a;
99	    return { ...a, externalLink: `${window.location.origin}/file/${a.name}/${a.filename}?share_token=${encodeURIComponent(token)}` };
100	  });
101	}
```

**`web/src/hooks/useFilteredMemoStats.ts`** — FilteredMemoStats(interface), useFilteredMemoStats(function), timestampsForBasis(function), UseFilteredMemoStatsOptions(interface), toDateString(function)

```typescript
1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import dayjs from "dayjs";
3	import { countBy } from "lodash-es";
4	import { useMemo } from "react";
5	import type { MemoExplorerContext } from "@/components/MemoExplorer";
6	import { type MemoTimeBasis, useView } from "@/contexts/ViewContext";
7	import useCurrentUser from "@/hooks/useCurrentUser";
8	import { useAllUserStats, useUserStats } from "@/hooks/useUserQueries";
9	import { State } from "@/types/proto/api/v1/common_pb";
10	import type { UserStats } from "@/types/proto/api/v1/user_service_pb";
11	import type { StatisticsData } from "@/types/statistics";
12	
13	export interface FilteredMemoStats {
14	  statistics: StatisticsData;
15	  tags: Record<string, number>;
16	  loading: boolean;
17	}
18	
19	export interface UseFilteredMemoStatsOptions {
20	  userName?: string;
21	  context?: MemoExplorerContext;
22	}
23	
24	const toDateString = (date: Date) => dayjs(date).format("YYYY-MM-DD");
25	
26	const timestampsForBasis = (stats: UserStats, basis: MemoTimeBasis) => {
27	  const createdArray = stats.memoCreatedTimestamps ?? [];
28	  const updatedArray = stats.memoUpdatedTimestamps ?? [];
29	  const wantUpdated = basis === "update_time";
30	  const oldServerFallback = wantUpdated && updatedArray.length === 0 && createdArray.length > 0;
31	  if (oldServerFallback) {
32	    console.warn("UserStats.memo_updated_timestamps not present; falling back to memo_created_timestamps");
33	  }
34	  return wantUpdated && !oldServerFallback ? updatedArray : createdArray;
35	};
36	
37	export const useFilteredMemoStats = (options: UseFilteredMemoStatsOptions = {}): FilteredMemoStats => {
38	  const { userName, context } = options;
39	  const currentUser = useCurrentUser();
40	  const { timeBasis } = useView();
41	
42	  // home/profile: use backend per-user stats (full tag set, not page-limited)
43	  const { data: userStats, isLoading: isLoadingUserStats } = useUserStats(userName);
44	  // explore/archived: fetch backend grouped stats and aggregate them locally.
45	  // ListAllUserStats AND's the request filter with the server's auth filter, so
46	  // private memos are not included unless explicitly visible to the current user.
47	  const exploreVisibilityFilter = currentUser != null ? 'visibility in ["PUBLIC", "PROTECTED"]' : 'visibility in ["PUBLIC"]';
48	  const allUserStatsRequest =
49	    context === "explore"
50	      ? { state: State.NORMAL, filter: exploreVisibilityFilter }
51	      : context === "archived"
52	        ? { state: State.ARCHIVED }
53	        : {};
54	  const shouldFetchAllUserStats = context === "explore" || (context === "archived" && !!currentUser?.name);
55	  const { data: allUserStats = [], isLoading: isLoadingAllUserStats } = useAllUserStats(allUserStatsRequest, {
56	    enabled: shouldFetchAllUserStats,
57	  });
58	
59	  const data = useMemo(() => {
60	    const loading = isLoadingUserStats || isLoadingAllUserStats;
61	    let activityStats: Record<string, number> = {};
62	    let tagCount: Record<string, number> = {};
63	
64	    if (context === "explore" || context === "archived") {
65	      const displayDates: string[] = [];
66	      for (const stats of allUserStats) {
67	        for (const [tag, count] of Object.entries(stats.tagCount ?? {})) {
68	          tagCount[tag] = (tagCount[tag] ?? 0) + count;
69	        }
70	        displayDates.push(
71	          ...timestampsForBasis(stats, timeBasis)
72	            .map((ts) => (ts ? timestampDate(ts) : undefined))
73	            .filter((date): date is Date => date !== undefined)
74	            .map(toDateString),
75	        );
76	      }
77	      activityStats = countBy(displayDates);
78	    } else if (userName && userStats) {
79	      // home/profile: use backend per-user stats.
80	      const sourceArray = timestampsForBasis(userStats, timeBasis);
81	      if (sourceArray.length > 0) {
82	        activityStats = countBy(
83	          sourceArray
84	            .map((ts) => (ts ? timestampDate(ts) : undefined))
85	            .filter((date): date is Date => date !== undefined)
86	            .map(toDateString),
87	        );
88	      }
89	      if (userStats.tagCount) {
90	        tagCount = userStats.tagCount;
91	      }
92	    }
93	
94	    return { statistics: { activityStats, timeBasis }, tags: tagCount, loading };
95	  }, [context, userName, userStats, allUserStats, isLoadingUserStats, isLoadingAllUserStats, timeBasis]);
96	
97	  return data;
98	};
```


